import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';
import { SessionBar } from './core/session-bar';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink, SessionBar],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <app-session-bar />
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
];
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

// The app's wiring: the router and the HTTP client.
export const appConfig: ApplicationConfig = {
  providers: [provideBrowserGlobalErrorListeners(), provideRouter(routes), provideHttpClient()],
};
import { Component, inject, signal } from '@angular/core';
import { Session } from './session';

// Sign-in by name (no password), the signed-in name, and the sheet chooser with the active id.
@Component({
  selector: 'app-session-bar',
  template: `
    @if (session.user(); as user) {
      <section class="bar" aria-label="Session">
        <span
          >Signed in as <strong data-testid="current-user">{{ user }}</strong></span
        >
        <form (submit)="load($event)">
          <label for="sheet-id">Sheet</label>
          <input
            id="sheet-id"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set(false)"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
        </form>
        @if (session.sheetId(); as sheet) {
          <span
            >Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></span
          >
        }
        @if (sheetError()) {
          <p role="alert" class="error" data-testid="sheet-load-error">
            That sheet could not be loaded.
          </p>
        }
      </section>
    } @else {
      <form class="bar" (submit)="signIn($event)" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(false)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError()) {
          <p role="alert" class="error" data-testid="signin-error">Type a name to sign in.</p>
        }
      </form>
    }
  `,
  styles: `
    .bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      padding: 0.5rem 0;
    }
    form {
      display: flex;
      gap: 0.5rem;
      align-items: center;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
  `,
})
export class SessionBar {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal(false);
  protected readonly sheetError = signal(false);

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected signIn(event: Event): void {
    event.preventDefault();
    this.signinError.set(!this.session.signIn(this.nameInput()));
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(false);
    this.sheetError.set(!(await this.session.loadSheet(this.sheetInput())));
  }
}
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
}

// Who is signed in and which sheet is active. Every request to the server carries the signed-in
// name in the X-User header (see `headers()`); everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  readonly signedIn = computed(() => this.user() !== null);

  signIn(name: string): boolean {
    const user = name.trim();
    if (!user) return false;
    this.user.set(user);
    this.sheetId.set(null);
    return true;
  }

  headers(): HttpHeaders {
    return new HttpHeaders({ 'X-User': this.user() ?? '' });
  }

  /** Load a sheet by id (starting it empty if never used); resolves false when refused. */
  async loadSheet(id: string): Promise<boolean> {
    const sheet = id.trim();
    if (!sheet || !this.user()) return false;
    try {
      const view = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sheet)}/load`, null, {
          headers: this.headers(),
        }),
      );
      this.sheetId.set(view.id);
      return true;
    } catch {
      return false;
    }
  }
}
import { Component, inject } from '@angular/core';
import { Session } from '../../core/session';

// The home page: the active sheet's content. A page is an Angular component like this one, plus
// one entry in app.routes.ts.
@Component({
  selector: 'app-home',
  template: `
    @if (session.sheetId()) {
      <p data-testid="home-empty">Nothing here yet.</p>
    } @else if (session.signedIn()) {
      <p data-testid="home-no-sheet">Load a sheet to begin.</p>
    } @else {
      <p data-testid="home-signed-out">Sign in to begin.</p>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )

